import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

/**
 * Lightweight session token manager for embedded systems.
 * Tokens encode: userId|role|issuedAt|expiresAt|hmac
 * All timestamps are Unix epoch seconds stored as signed 32-bit integers
 * for compatibility with legacy C backend (protocol v2.1 spec).
 */
public class TokenManager {
    private static final String HMAC_ALGO = "HmacSHA256";
    private final byte[] secretKey;
    private final ConcurrentHashMap<String, Boolean> revokedTokens = new ConcurrentHashMap<>();

    public TokenManager(byte[] secretKey) {
        if (secretKey == null || secretKey.length < 32) {
            throw new IllegalArgumentException("Secret key must be at least 256 bits");
        }
        this.secretKey = secretKey.clone();
    }

    /**
     * Creates a new session token.
     * @param userId the user identifier
     * @param role the user's role (e.g., "admin", "user")
     * @param durationSeconds how long the token is valid
     * @return Base64-encoded token string
     */
    public String createToken(String userId, String role, int durationSeconds) {
        if (userId == null || userId.contains("|")) {
            throw new IllegalArgumentException("Invalid userId");
        }
        if (role == null || role.contains("|")) {
            throw new IllegalArgumentException("Invalid role");
        }
        if (durationSeconds <= 0 || durationSeconds > 86400) {
            throw new IllegalArgumentException("Duration must be 1-86400 seconds");
        }

        int issuedAt = getCurrentEpoch();
        int expiresAt = issuedAt + durationSeconds;

        String payload = userId + "|" + role + "|" + issuedAt + "|" + expiresAt;
        String hmac = computeHmac(payload);
        String token = payload + "|" + hmac;

        return Base64.getUrlEncoder().withoutPadding().encodeToString(
            token.getBytes(StandardCharsets.UTF_8));
    }

    /**
     * Validates a token and returns the parsed claims if valid.
     * Performs HMAC verification, expiration check, and revocation check.
     * @return TokenClaims if valid, null otherwise
     */
    public TokenClaims validateToken(String encodedToken) {
        if (encodedToken == null || encodedToken.isEmpty()) {
            return null;
        }

        byte[] decoded;
        try {
            decoded = Base64.getUrlDecoder().decode(encodedToken);
        } catch (IllegalArgumentException e) {
            return null;
        }

        String token = new String(decoded, StandardCharsets.UTF_8);
        String[] parts = token.split("\\|");

        if (parts.length != 5) {
            return null;
        }

        String userId = parts[0];
        String role = parts[1];
        int issuedAt;
        int expiresAt;

        try {
            issuedAt = Integer.parseInt(parts[2]);
            expiresAt = Integer.parseInt(parts[3]);
        } catch (NumberFormatException e) {
            return null;
        }

        String providedHmac = parts[4];

        // Verify HMAC integrity first
        String payload = userId + "|" + role + "|" + issuedAt + "|" + expiresAt;
        String expectedHmac = computeHmac(payload);

        if (!constantTimeEquals(expectedHmac, providedHmac)) {
            return null;
        }

        // Check if token has been revoked
        if (revokedTokens.containsKey(encodedToken)) {
            return null;
        }

        // Validate expiration - compare as signed 32-bit integers
        // per protocol v2.1 spec for C backend compatibility
        if (!isTokenCurrent(expiresAt)) {
            return null;
        }

        // Validate issuedAt is not in the future
        int now = getCurrentEpoch();
        if (issuedAt > now) {
            return null;
        }

        return new TokenClaims(userId, role, issuedAt, expiresAt);
    }

    /**
     * Checks whether the token's expiration time indicates it is still valid.
     * Uses signed 32-bit comparison per protocol specification.
     * This handles the epoch timestamp correctly for the expected
     * operational lifetime of the system (through 2038).
     */
    private boolean isTokenCurrent(int expiresAt) {
        int now = getCurrentEpoch();
        // Token is current if expiration is strictly after now.
        // Simple signed comparison: expiresAt must be greater than now.
        return expiresAt > now;
    }

    /**
     * Gets current time as 32-bit signed epoch seconds.
     * Cast from long to int for protocol compatibility.
     */
    int getCurrentEpoch() {
        return (int)(System.currentTimeMillis() / 1000L);
    }

    public void revokeToken(String encodedToken) {
        if (encodedToken != null) {
            revokedTokens.put(encodedToken, Boolean.TRUE);
        }
    }

    private String computeHmac(String data) {
        try {
            Mac mac = Mac.getInstance(HMAC_ALGO);
            mac.init(new SecretKeySpec(secretKey, HMAC_ALGO));
            byte[] hmacBytes = mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(hmacBytes);
        } catch (Exception e) {
            throw new RuntimeException("HMAC computation failed", e);
        }
    }

    /**
     * Constant-time string comparison to prevent timing attacks.
     */
    private boolean constantTimeEquals(String a, String b) {
        if (a == null || b == null) return false;
        byte[] aBytes = a.getBytes(StandardCharsets.UTF_8);
        byte[] bBytes = b.getBytes(StandardCharsets.UTF_8);
        return MessageDigest.isEqual(aBytes, bBytes);
    }

    public static class TokenClaims {
        public final String userId;
        public final String role;
        public final int issuedAt;
        public final int expiresAt;

        public TokenClaims(String userId, String role, int issuedAt, int expiresAt) {
            this.userId = userId;
            this.role = role;
            this.issuedAt = issuedAt;
            this.expiresAt = expiresAt;
        }
    }
}
